/**
 * Briefs: the question format and the answer format.
 *
 * The question format is the one the Aumera brief was written in
 * (`{id, t, d, q: [{id, type, q, hint, opts, found}]}`), so a brief written by
 * hand imports as a template unchanged. IDs are slugs generated by the builder,
 * never derived from the question text: renaming a question keeps its answers.
 */
import { z } from "zod";

export const TIPOS_DE_PERGUNTA = ["confirm", "one", "many", "text", "long", "file"] as const;
export type TipoDePergunta = (typeof TIPOS_DE_PERGUNTA)[number];

/** The fixed answers of a `confirm` question. Shown in the brief's language by the page. */
export const OPCOES_DE_CONFIRMACAO = ["Yes, that’s right", "Partly", "Not quite"] as const;

const slug = z.string().regex(/^[a-z0-9_-]{1,64}$/);
const texto = (max: number) => z.string().trim().min(1).max(max);
const opcional = (max: number) => z.string().trim().max(max).optional();

export const perguntaSchema = z
  .object({
    id: slug,
    type: z.enum(TIPOS_DE_PERGUNTA),
    q: texto(1000),
    hint: opcional(1000),
    opts: z.array(texto(200)).max(30).optional(),
    found: opcional(1000),
  })
  .strict()
  .superRefine((p, ctx) => {
    if ((p.type === "one" || p.type === "many") && !(p.opts && p.opts.length >= 2)) {
      ctx.addIssue({ code: "custom", message: "A choice question needs at least two options.", path: ["opts"] });
    }
  });
export type Pergunta = z.infer<typeof perguntaSchema>;

export const secaoSchema = z
  .object({
    id: slug,
    t: texto(200),
    d: opcional(1000),
    q: z.array(perguntaSchema).max(60),
  })
  .strict();
export type Secao = z.infer<typeof secaoSchema>;

export const secoesSchema = z
  .array(secaoSchema)
  .max(40)
  .superRefine((secoes, ctx) => {
    const vistas = new Set<string>();
    secoes.forEach((s, i) => {
      if (vistas.has(s.id)) ctx.addIssue({ code: "custom", message: `Duplicate section id ${s.id}`, path: [i, "id"] });
      vistas.add(s.id);
      const perguntas = new Set<string>();
      s.q.forEach((p, j) => {
        if (perguntas.has(p.id)) ctx.addIssue({ code: "custom", message: `Duplicate question id ${p.id}`, path: [i, "q", j, "id"] });
        perguntas.add(p.id);
      });
    });
  });

/** A file the client uploaded. `path` is the object path inside the `briefs` bucket. */
export const arquivoSchema = z
  .object({
    path: z.string().min(1).max(500),
    name: z.string().trim().min(1).max(255),
    type: z.string().max(200).default(""),
    size: z.number().int().min(0).max(20 * 1024 * 1024),
  })
  .strict();
export type ArquivoDoBrief = z.infer<typeof arquivoSchema>;

export const MAX_ARQUIVOS_POR_PERGUNTA = 30;

export type RespostaDaSecao = {
  v: Record<string, string | string[]>;
  files: Record<string, ArquivoDoBrief[]>;
  updatedAt?: string;
};

const respostaBrutaSchema = z
  .object({
    v: z.record(z.string(), z.union([z.string().max(20000), z.array(z.string().max(200)).max(30)])).default({}),
    files: z.record(z.string(), z.array(arquivoSchema).max(MAX_ARQUIVOS_POR_PERGUNTA)).default({}),
  })
  .strict();

/**
 * Checks one section of answers against the brief's own questions. Only known
 * question ids (and their `__note` / `__link` companions) are kept, choices must
 * be among the question's options, and files must sit under this brief's folder.
 */
export function validarRespostaDaSecao(
  secao: Secao,
  bruto: unknown,
  prefixoDosArquivos: string,
): { ok: true; resposta: RespostaDaSecao } | { ok: false; erro: string } {
  const parsed = respostaBrutaSchema.safeParse(bruto);
  if (!parsed.success) return { ok: false, erro: "invalid_payload" };
  const porId = new Map(secao.q.map((p) => [p.id, p]));
  const v: RespostaDaSecao["v"] = {};

  for (const [chave, valor] of Object.entries(parsed.data.v)) {
    const [id, sufixo] = chave.split("__");
    const p = id ? porId.get(id) : undefined;
    if (!p) return { ok: false, erro: `unknown_question:${chave}` };
    if (sufixo !== undefined) {
      if (!(sufixo === "note" || (sufixo === "link" && p.type === "file")) || typeof valor !== "string") {
        return { ok: false, erro: `invalid_field:${chave}` };
      }
      v[chave] = valor;
      continue;
    }
    if (p.type === "file") return { ok: false, erro: `invalid_field:${chave}` };
    const opcoes: readonly string[] = p.type === "confirm" ? OPCOES_DE_CONFIRMACAO : (p.opts ?? []);
    if (p.type === "many") {
      if (!Array.isArray(valor) || valor.some((o) => !opcoes.includes(o))) return { ok: false, erro: `invalid_choice:${chave}` };
    } else if (p.type === "one" || p.type === "confirm") {
      if (typeof valor !== "string" || (valor !== "" && !opcoes.includes(valor))) return { ok: false, erro: `invalid_choice:${chave}` };
    } else if (typeof valor !== "string") {
      return { ok: false, erro: `invalid_field:${chave}` };
    }
    v[chave] = valor;
  }

  const files: RespostaDaSecao["files"] = {};
  for (const [id, lista] of Object.entries(parsed.data.files)) {
    const p = porId.get(id);
    if (!p || p.type !== "file") return { ok: false, erro: `invalid_files:${id}` };
    if (lista.some((a) => !a.path.startsWith(prefixoDosArquivos) || a.path.includes(".."))) {
      return { ok: false, erro: `invalid_file_path:${id}` };
    }
    files[id] = lista;
  }
  return { ok: true, resposta: { v, files, updatedAt: new Date().toISOString() } };
}

/** How many questions of the brief have an answer: a value, a note, a link or a file. */
export function progressoDoBrief(secoes: Secao[], respostas: Record<string, RespostaDaSecao | undefined>) {
  let total = 0;
  let respondidas = 0;
  for (const s of secoes) {
    const r = respostas[s.id];
    for (const p of s.q) {
      total++;
      if (r && perguntaRespondida(p, r)) respondidas++;
    }
  }
  return { total, respondidas };
}

export function perguntaRespondida(p: Pergunta, r: RespostaDaSecao): boolean {
  if (p.type === "file") return (r.files[p.id]?.length ?? 0) > 0 || !!String(r.v[`${p.id}__link`] ?? "").trim();
  const a = r.v[p.id];
  const nota = String(r.v[`${p.id}__note`] ?? "").trim();
  return (Array.isArray(a) ? a.length > 0 : !!String(a ?? "").trim()) || !!nota;
}

/** The answers as plain text, section by section: what "Export" downloads. */
export function respostasEmTexto(
  titulo: string,
  secoes: Secao[],
  respostas: Record<string, RespostaDaSecao | undefined>,
): string {
  const linhas = [titulo.toUpperCase(), `Exported ${new Date().toISOString().slice(0, 10)}`, ""];
  secoes.forEach((s, si) => {
    linhas.push("", `== ${si + 1}. ${s.t.toUpperCase()} ==`);
    const r = respostas[s.id] ?? { v: {}, files: {} };
    s.q.forEach((p, qi) => {
      const partes: string[] = [];
      const a = r.v[p.id];
      const valor = Array.isArray(a) ? a.join(", ") : String(a ?? "").trim();
      if (valor) partes.push(valor);
      const nota = String(r.v[`${p.id}__note`] ?? "").trim();
      if (nota) partes.push(`Note: ${nota}`);
      const link = String(r.v[`${p.id}__link`] ?? "").trim();
      if (link) partes.push(`Link: ${link}`);
      for (const f of r.files[p.id] ?? []) partes.push(`File: ${f.name}`);
      linhas.push("", `${si + 1}.${qi + 1} ${p.q}`, partes.length ? partes.join("\n") : "(skipped)");
    });
  });
  return linhas.join("\n");
}

/** A new random slug for a section or question created in the builder. */
export function novoIdDoBuilder(prefixo: "s" | "q"): string {
  return `${prefixo}_${crypto.randomUUID().replace(/-/g, "").slice(0, 10)}`;
}
